final:
class Bad:
    n: int

def check(x: int) -> int fail Bad:
    """Return x when it is even; otherwise fail with Bad carrying x."""
    ex check(2) == 2
    ex check(3) == Err(Bad(n=3))
    if x % 2 != 0:
        fail Bad(n=x)
    return x

def all_even(xs: list[int]) -> list[int] fail Bad:
    """Check every element of xs in parallel. Return the list unchanged when all
    elements are even. Otherwise fail with the failure of the bad element with the
    lowest index, regardless of which parallel check finishes first."""
    post out == xs
    ex all_even([2, 4, 6]) == [2, 4, 6]
    ex all_even([2, 3, 5]) == Err(Bad(n=3))
    ex all_even([]) == []
    oks = par [check(x) else -1 for x in xs]
    for i in range(xs.len()):
        if oks[i] == -1:
            fail Bad(n=xs[i])
    return xs.copy()
